    try{std::lock_guard lock(impl_->process_mutex);if(cancel.stop_requested())throw ToolCancelled("Native worker process cancelled");if(!impl_->processes.IsValid())impl_->processes=impl_->call(impl_->worker,"Processes",{});auto input=sdk_values::to_value(impl_->runtime.host(),nlohmann::json::parse(invocation.serialize()));const auto result=nlohmann::json::parse(impl_->await(impl_->service_call(impl_->processes,impl_->process_methods,"Invoke",{input}),{},cancel));if(!result.is_object()||result.size()!=2||!result.at("success").is_boolean()||!result.at("output_json").is_string())throw ProcessOutcomeUnrecorded("Native process result differs");return {result.at("success").get<bool>(),result.at("output_json").get<std::string>()};}
    catch(const TransportCancelled&){throw ToolCancelled("Native worker process cancelled");}catch(const TransportTimeout&){throw ToolCancelled("Native worker process deadline elapsed");}catch(const AgentWorkerModelOutcomeUnrecorded&){throw ProcessOutcomeUnrecorded("Native worker process acknowledgement unavailable; no replay authorized");}catch(const nlohmann::json::exception&){throw ProcessOutcomeUnrecorded("Native worker process result invalid; no replay authorized");}
