std::vector<std::string> NativeWorkerModelClient::callable_names(std::stop_token cancel){
    try{std::lock_guard lock(impl_->callable_mutex);if(cancel.stop_requested())throw ToolCancelled("Native callable catalogue cancelled");if(!impl_->callables.IsValid())impl_->callables=impl_->call(impl_->worker,"Callables",{});const auto result=nlohmann::json::parse(impl_->await(impl_->service_call(impl_->callables,impl_->callable_methods,"Catalogue",{}),{},cancel));if(!result.is_array()||result.size()>64)throw ModelProtocolError("Invalid native callable catalogue");std::vector<std::string> names;for(const auto& value:result){if(!value.is_string())throw ModelProtocolError("Invalid native callable alias");auto name=value.get<std::string>();if(name.empty()||name.size()>128||name.find(char(0))!=std::string::npos||std::find(names.begin(),names.end(),name)!=names.end())throw ModelProtocolError("Invalid native callable alias");names.push_back(std::move(name));}return names;}
    catch(const TransportCancelled&){throw ToolCancelled("Native callable catalogue cancelled");}catch(const TransportTimeout&){throw ToolCancelled("Native callable catalogue expired");}catch(const AgentWorkerModelOutcomeUnrecorded&){throw AgentWorkerCallableOutcomeUnrecorded("Native callable catalogue unavailable; no replay authorized");}catch(const nlohmann::json::exception&){throw ModelProtocolError("Invalid native callable catalogue");}
}
bool NativeWorkerModelClient::process_join(const std::string& attempt,std::stop_token cancel){
    try{std::lock_guard lock(impl_->process_mutex);if(cancel.stop_requested())throw ToolCancelled("Native process join cancelled");if(!impl_->processes.IsValid())impl_->processes=impl_->call(impl_->worker,"Processes",{});const auto result=nlohmann::json::parse(impl_->await(impl_->service_call(impl_->processes,impl_->process_methods,"Join",{impl_->text(attempt)}),{},cancel));if(!result.is_object()||result.size()!=1||!result.at("joined").is_boolean())throw ProcessOutcomeUnrecorded("Native process join result differs");return result.at("joined").get<bool>();}
    catch(const TransportCancelled&){throw ToolCancelled("Native process join cancelled");}catch(const TransportTimeout&){throw ToolCancelled("Native process join deadline elapsed");}catch(const AgentWorkerModelOutcomeUnrecorded&){throw ProcessOutcomeUnrecorded("Native process join acknowledgement unavailable; no replay authorized");}catch(const nlohmann::json::exception&){throw ProcessOutcomeUnrecorded("Native process join result invalid; no replay authorized");}
}
